Mesh<Point, double> result;
std::vector<std::vector<Point>> faces;
std::vector<double> edge_lengths;

for (auto it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    auto e = *it;
    if (rt.is_infinite(e.first)) continue;

    double edge_len = std::sqrt(rt.segment(e).squared_length());
    if (edge_len > threshold) continue;

    std::vector<Point> polygon;
    std::vector<int> cell_indices;

    for (int i = 0; i < 2; ++i) {
        auto cell = e.first->neighbor(e.second[i]);
        if (rt.is_infinite(cell)) continue;
        Point p = rt.dual(cell);
        polygon.push_back(p);
        cell_indices.push_back(rt.index(cell));
    }

    if (polygon.size() == 2) {
        faces.push_back(polygon);
        edge_lengths.push_back(edge_len);
    }
}

for (size_t i = 0; i < faces.size(); ++i) {
    result.add_face(faces[i], edge_lengths[i]);
}

return result;

